actions.script:
const lib = ec.resource.script('component://mr-mantle/service/mantle/ledger/EntityLib.js')
rows = []
const attempt = (finding, serviceName, parameters) => {
    const row = {assetReservationId: finding.assetReservationId, orderId: finding.orderId,
        orderItemSeqId: finding.orderItemSeqId, reasonCode: finding.reasonCode}
    try {
        lib.probe(serviceName, parameters)
        rows.push(Object.assign(row, {ok: true}))
    } catch (error) {
        ec.logger.warn('Reservation repair of ' + finding.assetReservationId + ' failed: ' + error.message)
        rows.push(Object.assign(row, {ok: false, message: String(error.message)}))
    }
}
const elsewhere = new Map()
for (const finding of Array.from(preview.findings || [])) {
    if (finding.reasonCode !== 'AVAILABLE_ELSEWHERE')
        attempt(finding, 'mantle.product.AssetServices.check#AssetReservationValid',
            {assetReservationId: finding.assetReservationId})
    else elsewhere.set(finding.productId, (elsewhere.get(finding.productId) || []).concat([finding]))
}
// a product's not-available reservations move onto its available stock there, asset by asset
for (const [stockProductId, findings] of elsewhere) {
    const available = Array.from(lib.find('mantle.product.asset.Asset',
            {facilityId: facilityId, productId: stockProductId, statusId: 'AstAvailable'})
        .condition('availableToPromiseTotal', 'greater', 0).orderBy('assetId').selectField('assetId').list())
    const failures = []
    for (const asset of available) {
        try {
            lib.probe('mantle.product.AssetServices.reserve#IncreasedAsset', {assetId: asset.assetId})
        } catch (error) {
            ec.logger.warn('Reservation repair on asset ' + asset.assetId + ' failed: ' + error.message)
            failures.push(asset.assetId + ': ' + error.message)
        }
    }
    for (const finding of findings) {
        const after = lib.one('mantle.product.issuance.AssetReservation',
            {assetReservationId: finding.assetReservationId})
        const left = after?.quantityNotAvailable == null ? 0 : Number(String(after.quantityNotAvailable))
        rows.push({assetReservationId: finding.assetReservationId, orderId: finding.orderId,
            orderItemSeqId: finding.orderItemSeqId, reasonCode: finding.reasonCode, ok: left === 0,
            message: left === 0 ? null : [left + ' still not available'].concat(failures).join('; ')})
    }
}

const lib = ec.resource.script('component://mr-mantle/service/mantle/ledger/EntityLib.js')
const dayOf = value => (value == null || value === '' ? null : lib.calendarDateText(value))
const stampOf = value => (value == null || value === '' ? null : String(lib.ms(value)))
const wanted = {}
if (lotNumber != null && String(lotNumber).trim() !== '') wanted.lotNumber = String(lotNumber).trim()
if (mfgPartyId != null && mfgPartyId !== '') wanted.mfgPartyId = mfgPartyId
if (manufacturedDate != null && manufacturedDate !== '') wanted.manufacturedDate = manufacturedDate
if (clearExpirationDate) wanted.expirationDate = null
else if (expirationDate != null && expirationDate !== '') wanted.expirationDate = expirationDate
const same = {
    lotNumber: (a, b) => (a || null) === (b || null),
    mfgPartyId: (a, b) => (a || null) === (b || null),
    manufacturedDate: (a, b) => stampOf(a) === stampOf(b),
    expirationDate: (a, b) => dayOf(a) === dayOf(b)
}
const shown = {lotNumber: v => v || null, mfgPartyId: v => v || null,
    manufacturedDate: v => (v == null ? null : lib.dateText(v)), expirationDate: dayOf}
changes = Object.keys(wanted).filter(field => !same[field](lot[field], wanted[field]))
    .map(field => ({field, oldValue: shown[field](lot[field]), newValue: shown[field](wanted[field])}))
const expiry = changes.find(change => change.field === 'expirationDate')
expiryExtended = !!expiry && expiry.oldValue != null &&
    (expiry.newValue == null || expiry.newValue > expiry.oldValue)
otherChanges = changes.some(change => change.field !== 'expirationDate') || (!!expiry && !expiryExtended)
newValues = Object.fromEntries(changes.map(change => [change.field, wanted[change.field]]))
oldExpiration = expiry ? expiry.oldValue : null
mayExtend = lib.access.has('LOT_EXPIRY_EXTEND')
mayAdjust = lib.access.has('STOCK_ADJUST')
